import{_ as e,o,c as i,a2 as t}from"./chunks/framework.CqGPl1zp.js";const l="/newx-doc/assets/%E5%B7%A5%E4%BD%9C%E5%8F%B0.CuNHbKTz.png",h=JSON.parse('{"title":"移动端支付管理","description":"","frontmatter":{},"headers":[],"relativePath":"pay/mobile.md","filePath":"pay/mobile.md","lastUpdated":null}'),r={name:"pay/mobile.md"};function d(n,a,p,c,u,s){return o(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="移动端支付管理" tabindex="-1">移动端支付管理 <a class="header-anchor" href="#移动端支付管理" aria-label="Permalink to &quot;移动端支付管理&quot;">​</a></h1><p>友情提示</p><p>本文讲解 yudao 移动端（uni-app 版）的支付管理，重点说清楚两件事：支付模块<strong>已经提供手机端</strong>、当前支持的<strong>主要功能</strong>。</p><ul><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-uniapp" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-uniapp</a>，基于 <code>uni-app</code> + <code>Vue3</code> + <code>wot-ui</code> 实现，支持 H5、微信小程序等多端。</li><li>后端：复用 PC 端同一套 <code>yudao-module-pay</code> 模块与 <code>/pay/**</code> 接口，移动端只是换了一层 UI。</li></ul><h2 id="_1-移动端功能" tabindex="-1">1. 移动端功能 <a class="header-anchor" href="#_1-移动端功能" aria-label="Permalink to &quot;1. 移动端功能&quot;">​</a></h2><ul><li>交易管理：应用信息、支付订单、退款订单、回调通知、转账订单。</li><li>钱包管理：钱包余额、充值套餐、钱包流水。</li><li>接入示例：示例订单、示例提现。</li></ul><p><img src="'+l+'" alt="支付管理移动端"></p><h2 id="_2-启动与发布" tabindex="-1">2. 启动与发布 <a class="header-anchor" href="#_2-启动与发布" aria-label="Permalink to &quot;2. 启动与发布&quot;">​</a></h2><ul><li>启动：参考 <a href="./../quick-start-front">《快速启动【前端】》</a> 文档的「1.4 Vue3 + uni-app 版本」小节。</li><li>发布：参考 <a href="./../admin-uniapp/deploy">《运行发布》</a> 文档。</li></ul><p>启动完成后，在工作台选择「支付管理」即可进入。</p><h2 id="_3-代码位置" tabindex="-1">3. 代码位置 <a class="header-anchor" href="#_3-代码位置" aria-label="Permalink to &quot;3. 代码位置&quot;">​</a></h2><ul><li>页面：<code>src/pages-pay/</code></li><li>接口：<code>src/api/pay/</code></li></ul>',12)])])}const m=e(r,[["render",d]]);export{h as __pageData,m as default};
